        #include "log_formatter.h"

int format_log_records(char* log_data, int record_count, int record_size, char* output_buffer, int output_size) {
    if (!log_data || !output_buffer || record_count <= 0 || record_size <= 0 || output_size <= 0) {
        return -1;
    }

    // Check if the record_size is at least as large as our expected struct
    if (record_size < sizeof(struct log_record)) {
        return -1;
    }

    int total_written = 0;
    char temp_buffer[512]; // Temporary buffer for formatting each record

    for (int i = 0; i < record_count; i++) {
        // Calculate the position of the current record in the log_data buffer
        char* current_record_ptr = log_data + (i * record_size);

        // Verify we don't go out of bounds when reading the record
        if (current_record_ptr + record_size > log_data + (record_count * record_size)) {
            return -1;
        }

        // Cast the current position to a log_record struct
        struct log_record* current_record = (struct log_record*)current_record_ptr;

        // Verify that the message field is properly null-terminated within the record
        int message_len = 0;
        for (int j = 0; j < sizeof(current_record->message); j++) {
            if (current_record->message[j] == '\0') {
                message_len = j;
                break;
            }
        }
        if (message_len == 0 && current_record->message[sizeof(current_record->message)-1] != '\0') {
            // If no null terminator found and the last byte isn't null, 
            // we consider the message invalid or too long
            return -1;
        }

        // Format the log level to a readable string
        const char* level_str;
        switch (current_record->level) {
            case 0:
                level_str = "DEBUG";
                break;
            case 1:
                level_str = "INFO";
                break;
            case 2:
                level_str = "WARNING";
                break;
            case 3:
                level_str = "ERROR";
                break;
            default:
                level_str = "UNKNOWN";
                break;
        }

        // Format the timestamp to a readable string
        time_t timestamp = (time_t)current_record->timestamp;
        struct tm* timeinfo = localtime(&timestamp);
        char time_str[64];
        if (timeinfo) {
            strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", timeinfo);
        } else {
            strcpy(time_str, "INVALID-TIME");
        }

        // Format this record into the temporary buffer
        int written = snprintf(temp_buffer, sizeof(temp_buffer), 
                               "[%s] %s: %s\n", 
                               time_str, level_str, current_record->message);

        // Check if the formatted record is too large for our temporary buffer
        if (written >= sizeof(temp_buffer)) {
            return -1;
        }

        // Check if we have enough space in the output buffer for this record
        if (total_written + written >= output_size) {
            return -1; // Not enough space in output buffer
        }

        // Copy the formatted record to the output buffer
        memcpy(output_buffer + total_written, temp_buffer, written);
        total_written += written;
    }

    // Ensure the output buffer is null-terminated
    if (total_written < output_size) {
        output_buffer[total_written] = '\0';
    } else {
        output_buffer[output_size - 1] = '\0';
    }

    return total_written;
}
