#ifndef LOG_FORMATTER_H
#define LOG_FORMATTER_H

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>

struct log_record {
    unsigned long timestamp;
    unsigned char level;
    char message[256];
};

int format_log_records(char* log_data, int record_count, int record_size, char* output_buffer, int output_size);

#endif
